@@ -0,0 +1,137 @@
+using System.Net;
+using System.Net.Http.Json;
+using System.Text.Json;
+using Microsoft.EntityFrameworkCore;
+using Microsoft.Extensions.DependencyInjection;
+using WorkItems.Api.Data;
+using WorkItems.Api.Models;
+using Xunit;
+
+namespace WorkItems.Api.Tests;
+
+public sealed class ProcessOverdueAcceptanceTests
+{
+    [Fact]
+    public async Task ProcessOverdue_WhenDueExactlyNow_ProcessesOnlyTheBoundaryItem()
+    {
+        var cancellationToken = TestContext.Current.CancellationToken;
+        using var factory = new WorkItemsApiFactory();
+        using var client = factory.CreateClient();
+        var boundaryItem = CreateOpenWorkItem("剛好到期", factory.UtcNow);
+        var futureItem = CreateOpenWorkItem("尚未到期", factory.UtcNow.AddMilliseconds(1));
+        await SeedAsync(factory, cancellationToken, boundaryItem, futureItem);
+
+        using var response = await client.PostAsync(
+            "/api/work-items/process-overdue",
+            null,
+            cancellationToken);
+        var body = await response.Content.ReadAsStringAsync(cancellationToken);
+        using var json = JsonDocument.Parse(body);
+        var summary = JsonSerializer.Deserialize<ProcessOverdueContract>(
+            body,
+            JsonSerializerOptions.Web);
+
+        Assert.Equal(HttpStatusCode.OK, response.StatusCode);
+        Assert.NotNull(summary);
+        Assert.Equal(
+            [
+                "failedNotificationWorkItemIds",
+                "notificationAttemptCount",
+                "notificationFailureCount",
+                "processedCount"
+            ],
+            json.RootElement.EnumerateObject().Select(property => property.Name).Order().ToArray());
+        Assert.Equal(1, summary.ProcessedCount);
+        Assert.Equal(1, summary.NotificationAttemptCount);
+        Assert.Equal(0, summary.NotificationFailureCount);
+        Assert.Empty(summary.FailedNotificationWorkItemIds);
+        Assert.Equal([boundaryItem.Id], factory.Notifications.AttemptedWorkItemIds);
+
+        var persistedStatuses = await ReadStatusesAsync(factory, cancellationToken);
+        Assert.Equal("Overdue", persistedStatuses[boundaryItem.Id]);
+        Assert.Equal("Open", persistedStatuses[futureItem.Id]);
+    }
+
+    [Fact]
+    public async Task ProcessOverdue_WhenNotificationReportsFailure_PersistsAfterTheAttempt()
+    {
+        var cancellationToken = TestContext.Current.CancellationToken;
+        WorkItemsApiFactory? factoryForNotification = null;
+        string? persistedStatusDuringNotification = null;
+
+        using var factory = new WorkItemsApiFactory(
+            notificationHandler: async (workItem, token) =>
+            {
+                await using var scope = factoryForNotification!.Services.CreateAsyncScope();
+                var database = scope.ServiceProvider.GetRequiredService<WorkItemsDbContext>();
+                persistedStatusDuringNotification = await database.WorkItems
+                    .AsNoTracking()
+                    .Where(candidate => candidate.Id == workItem.Id)
+                    .Select(candidate => candidate.Status)
+                    .SingleAsync(token);
+                return false;
+            });
+        factoryForNotification = factory;
+
+        using var client = factory.CreateClient();
+        var workItem = CreateOpenWorkItem("通知失敗仍須儲存", factory.UtcNow.AddMinutes(-1));
+        await SeedAsync(factory, cancellationToken, workItem);
+
+        using var response = await client.PostAsync(
+            "/api/work-items/process-overdue",
+            null,
+            cancellationToken);
+        var summary = await response.Content.ReadFromJsonAsync<ProcessOverdueContract>(
+            cancellationToken: cancellationToken);
+
+        Assert.Equal(HttpStatusCode.OK, response.StatusCode);
+        Assert.NotNull(summary);
+        Assert.Equal(1, summary.ProcessedCount);
+        Assert.Equal(1, summary.NotificationAttemptCount);
+        Assert.Equal(1, summary.NotificationFailureCount);
+        Assert.Equal([workItem.Id], summary.FailedNotificationWorkItemIds);
+        Assert.Equal([workItem.Id], factory.Notifications.AttemptedWorkItemIds);
+        Assert.Equal("Open", persistedStatusDuringNotification);
+
+        var persistedStatuses = await ReadStatusesAsync(factory, cancellationToken);
+        Assert.Equal("Overdue", persistedStatuses[workItem.Id]);
+    }
+
+    private static WorkItem CreateOpenWorkItem(string title, DateTimeOffset dueAtUtc) =>
+        new()
+        {
+            Id = Guid.NewGuid(),
+            Title = title,
+            Priority = "Normal",
+            DueAtUtc = dueAtUtc,
+            CreatedAtUtc = dueAtUtc.AddDays(-1)
+        };
+
+    private static async Task SeedAsync(
+        WorkItemsApiFactory factory,
+        CancellationToken cancellationToken,
+        params WorkItem[] workItems)
+    {
+        await using var scope = factory.Services.CreateAsyncScope();
+        var database = scope.ServiceProvider.GetRequiredService<WorkItemsDbContext>();
+        database.WorkItems.AddRange(workItems);
+        await database.SaveChangesAsync(cancellationToken);
+    }
+
+    private static async Task<Dictionary<Guid, string>> ReadStatusesAsync(
+        WorkItemsApiFactory factory,
+        CancellationToken cancellationToken)
+    {
+        await using var scope = factory.Services.CreateAsyncScope();
+        var database = scope.ServiceProvider.GetRequiredService<WorkItemsDbContext>();
+        return await database.WorkItems
+            .AsNoTracking()
+            .ToDictionaryAsync(item => item.Id, item => item.Status, cancellationToken);
+    }
+
+    private sealed record ProcessOverdueContract(
+        int ProcessedCount,
+        int NotificationAttemptCount,
+        int NotificationFailureCount,
+        Guid[] FailedNotificationWorkItemIds);
+}

