+using Microsoft.Extensions.Options;
+using WorkItems.Api.Models;
+using WorkItems.Api.Notifications;
+using Xunit;
+
+namespace WorkItems.Api.Tests;
+
+/// <summary>
+/// 驗證 Demo 通知供應商遵守 Use Case 所依賴的通知 Gateway 契約。
+/// </summary>
+public sealed class NotificationGatewayContractTests
+{
+    [Theory]
+    [InlineData(NotificationKind.Overdue, true)]
+    [InlineData(NotificationKind.Overdue, false)]
+    [InlineData(NotificationKind.Escalation, true)]
+    [InlineData(NotificationKind.Escalation, false)]
+    public async Task SendAsync_ReturnsProviderResult(
+        NotificationKind notificationKind,
+        bool expectedResult)
+    {
+        var cancellationToken = TestContext.Current.CancellationToken;
+        var (gateway, workItem) = CreateScenario(expectedResult);
+
+        var actualResult = await SendAsync(
+            gateway,
+            notificationKind,
+            workItem,
+            cancellationToken);
+
+        Assert.Equal(expectedResult, actualResult);
+    }
+
+    [Theory]
+    [InlineData(NotificationKind.Overdue)]
+    [InlineData(NotificationKind.Escalation)]
+    public async Task SendAsync_WhenCancellationIsRequested_PropagatesCancellation(
+        NotificationKind notificationKind)
+    {
+        var (gateway, workItem) = CreateScenario(notificationSucceeds: true);
+        using var cancellation = new CancellationTokenSource();
+        cancellation.Cancel();
+
+        var exception = await Assert.ThrowsAsync<OperationCanceledException>(
+            () => SendAsync(gateway, notificationKind, workItem, cancellation.Token));
+
+        Assert.Equal(cancellation.Token, exception.CancellationToken);
+    }
+
+    private static (INotificationGateway Gateway, WorkItem WorkItem) CreateScenario(
+        bool notificationSucceeds)
+    {
+        const string failureTitleMarker = "[notify-fail]";
+        var options = Options.Create(
+            new DemoNotificationOptions
+            {
+                FailureTitleMarker = failureTitleMarker
+            });
+        var workItem = new WorkItem
+        {
+            Id = Guid.NewGuid(),
+            Title = notificationSucceeds
+                ? "通知成功"
+                : $"通知失敗 {failureTitleMarker}"
+        };
+
+        return (new DemoNotificationGateway(options), workItem);
+    }
+
+    private static Task<bool> SendAsync(
+        INotificationGateway gateway,
+        NotificationKind notificationKind,
+        WorkItem workItem,
+        CancellationToken cancellationToken) =>
+        notificationKind switch
+        {
+            NotificationKind.Overdue => gateway.SendOverdueAsync(workItem, cancellationToken),
+            NotificationKind.Escalation => gateway.SendEscalationAsync(workItem, cancellationToken),
+            _ => throw new ArgumentOutOfRangeException(
+                nameof(notificationKind),
+                notificationKind,
+                "未知的通知種類。")
+        };
+
+    /// <summary>
+    /// 表示通知 Gateway 支援的通知種類。
+    /// </summary>
+    public enum NotificationKind
+    {
+        /// <summary>
+        /// 一般逾期通知。
+        /// </summary>
+        Overdue,
+
+        /// <summary>
+        /// 逾期升級通知。
+        /// </summary>
+        Escalation
+    }
+}

