@@ -0,0 +1,49 @@
+using System.Collections.Concurrent;
+
+namespace WorkItems.Api;
+
+/// <summary>
+/// 防止同一個應用程式執行個體同時處理同一筆工作項目。
+/// </summary>
+/// <remarks>
+/// 此協調只涵蓋共用目前 Singleton 的 HTTP 與背景工作；不同 Process 之間不共用狀態。
+/// </remarks>
+public sealed class InFlightWorkItemProcessingGate
+{
+    private readonly ConcurrentDictionary<Guid, byte> processingWorkItemIds = new();
+
+    /// <summary>
+    /// 嘗試登記正在處理的工作項目。
+    /// </summary>
+    /// <param name="workItemId">工作項目識別碼。</param>
+    /// <param name="cancellationToken">取消權杖。</param>
+    /// <returns>成功登記時回傳用來解除登記的範圍；同一項目已在處理時回傳 <see langword="null"/>。</returns>
+    public IDisposable? TryEnter(Guid workItemId, CancellationToken cancellationToken)
+    {
+        cancellationToken.ThrowIfCancellationRequested();
+
+        return processingWorkItemIds.TryAdd(workItemId, 0)
+            ? new Registration(this, workItemId)
+            : null;
+    }
+
+    private void Exit(Guid workItemId)
+    {
+        processingWorkItemIds.TryRemove(workItemId, out _);
+    }
+
+    private sealed class Registration(
+        InFlightWorkItemProcessingGate owner,
+        Guid workItemId) : IDisposable
+    {
+        private int isDisposed;
+
+        public void Dispose()
+        {
+            if (Interlocked.Exchange(ref isDisposed, 1) == 0)
+            {
+                owner.Exit(workItemId);
+            }
+        }
+    }
+}
diff --git a/tests/WorkItems.Api.Tests/ConcurrentOverdueProcessingTests.cs b/tests/WorkItems.Api.Tests/ConcurrentOverdueProcessingTests.cs
