index 0000000..2a1c5c9
--- /dev/null
+++ b/tests/WorkItems.Api.Tests/ConcurrentOverdueProcessingTests.cs
@@ -0,0 +1,192 @@
+using System.Net;
+using System.Net.Http.Json;
+using Microsoft.EntityFrameworkCore;
+using Microsoft.Extensions.DependencyInjection;
+using Microsoft.Extensions.Logging.Abstractions;
+using Microsoft.Extensions.Options;
+using WorkItems.Api.Data;
+using WorkItems.Api.Models;
+using Xunit;
+
+namespace WorkItems.Api.Tests;
+
+public sealed class ConcurrentOverdueProcessingTests
+{
+    [Fact]
+    public async Task HttpAndWorker_WhenProcessingSameWorkItemConcurrently_SendOneNotification()
+    {
+        var cancellationToken = TestContext.Current.CancellationToken;
+        var firstNotificationStarted = new TaskCompletionSource(
+            TaskCreationOptions.RunContinuationsAsynchronously);
+        var releaseFirstNotification = new TaskCompletionSource(
+            TaskCreationOptions.RunContinuationsAsynchronously);
+        var notificationCallCount = 0;
+
+        using var factory = new WorkItemsApiFactory(
+            notificationHandler: async (_, token) =>
+            {
+                if (Interlocked.Increment(ref notificationCallCount) == 1)
+                {
+                    firstNotificationStarted.TrySetResult();
+                    await releaseFirstNotification.Task.WaitAsync(token);
+                }
+
+                return true;
+            });
+        using var client = factory.CreateClient();
+        var workItem = new WorkItem
+        {
+            Id = Guid.NewGuid(),
+            Title = "HTTP 與排程並行處理",
+            Priority = "Normal",
+            DueAtUtc = factory.UtcNow.AddHours(-1),
+            CreatedAtUtc = factory.UtcNow.AddDays(-1)
+        };
+        await SeedAsync(factory, workItem, cancellationToken);
+        var worker = new OverdueProcessingWorker(
+            factory.Services.GetRequiredService<IServiceScopeFactory>(),
+            Options.Create(
+                new OverdueProcessingOptions
+                {
+                    Enabled = true,
+                    IntervalSeconds = 3600
+                }),
+            TimeProvider.System,
+            NullLogger<OverdueProcessingWorker>.Instance);
+
+        await worker.StartAsync(cancellationToken);
+        await firstNotificationStarted.Task.WaitAsync(cancellationToken);
+
+        try
+        {
+            using var response = await client.PostAsync(
+                "/api/work-items/process-overdue",
+                null,
+                cancellationToken);
+            var summary = await response.Content.ReadFromJsonAsync<ProcessOverdueContract>(
+                cancellationToken: cancellationToken);
+
+            Assert.Equal(HttpStatusCode.OK, response.StatusCode);
+            Assert.NotNull(summary);
+            Assert.Equal(0, summary.ProcessedCount);
+            Assert.Equal(0, summary.NotificationAttemptCount);
+            Assert.Equal(0, summary.NotificationFailureCount);
+            Assert.Empty(summary.FailedNotificationWorkItemIds);
+        }
+        finally
+        {
+            releaseFirstNotification.TrySetResult();
+            await WaitForPersistedStatusAsync(
+                factory,
+                workItem.Id,
+                "Overdue",
+                cancellationToken);
+            await worker.StopAsync(cancellationToken);
+            worker.Dispose();
+        }
+
+        Assert.Equal([workItem.Id], factory.Notifications.AttemptedWorkItemIds);
+        await using var verificationScope = factory.Services.CreateAsyncScope();
+        var database = verificationScope.ServiceProvider.GetRequiredService<WorkItemsDbContext>();
+        var persistedStatus = await database.WorkItems
+            .AsNoTracking()
+            .Where(candidate => candidate.Id == workItem.Id)
+            .Select(candidate => candidate.Status)
+            .SingleAsync(cancellationToken);
+        Assert.Equal("Overdue", persistedStatus);
+    }
+
+    [Fact]
+    public async Task ProcessOverdue_WhenAcknowledgementIsLost_AllowsExistingRetry()
+    {
+        var cancellationToken = TestContext.Current.CancellationToken;
+        var notificationCallCount = 0;
+        using var factory = new WorkItemsApiFactory(
+            notificationHandler: (_, _) =>
+            {
+                if (Interlocked.Increment(ref notificationCallCount) == 1)
+                {
+                    throw new InvalidOperationException("通知已送出，但 ACK 遺失。");
+                }
+
+                return Task.FromResult(true);
+            });
+        using var client = factory.CreateClient();
+        var workItem = new WorkItem
+        {
+            Id = Guid.NewGuid(),
+            Title = "Lost ACK 後重試",
+            Priority = "Normal",
+            DueAtUtc = factory.UtcNow.AddHours(-1),
+            CreatedAtUtc = factory.UtcNow.AddDays(-1)
+        };
+        await SeedAsync(factory, workItem, cancellationToken);
+
+        using var lostAcknowledgementResponse = await client.PostAsync(
+            "/api/work-items/process-overdue",
+            null,
+            cancellationToken);
+        using var retryResponse = await client.PostAsync(
+            "/api/work-items/process-overdue",
+            null,
+            cancellationToken);
+        var retrySummary = await retryResponse.Content.ReadFromJsonAsync<ProcessOverdueContract>(
+            cancellationToken: cancellationToken);
+
+        Assert.Equal(HttpStatusCode.InternalServerError, lostAcknowledgementResponse.StatusCode);
+        Assert.Equal(HttpStatusCode.OK, retryResponse.StatusCode);
+        Assert.NotNull(retrySummary);
+        Assert.Equal(1, retrySummary.ProcessedCount);
+        Assert.Equal(1, retrySummary.NotificationAttemptCount);
+        Assert.Equal([workItem.Id, workItem.Id], factory.Notifications.AttemptedWorkItemIds);
+        await using var verificationScope = factory.Services.CreateAsyncScope();
+        var database = verificationScope.ServiceProvider.GetRequiredService<WorkItemsDbContext>();
+        var persistedStatus = await database.WorkItems
+            .AsNoTracking()
+            .Where(candidate => candidate.Id == workItem.Id)
+            .Select(candidate => candidate.Status)
+            .SingleAsync(cancellationToken);
+        Assert.Equal("Overdue", persistedStatus);
+    }
+
+    private static async Task WaitForPersistedStatusAsync(
+        WorkItemsApiFactory factory,
+        Guid workItemId,
+        string expectedStatus,
+        CancellationToken cancellationToken)
+    {
+        while (true)
+        {
+            await using var scope = factory.Services.CreateAsyncScope();
+            var database = scope.ServiceProvider.GetRequiredService<WorkItemsDbContext>();
+            var status = await database.WorkItems
+                .AsNoTracking()
+                .Where(candidate => candidate.Id == workItemId)
+                .Select(candidate => candidate.Status)
+                .SingleAsync(cancellationToken);
+            if (status == expectedStatus)
+            {
+                return;
+            }
+
+            await Task.Delay(TimeSpan.FromMilliseconds(10), cancellationToken);
+        }
+    }
+
+    private static async Task SeedAsync(
+        WorkItemsApiFactory factory,
+        WorkItem workItem,
+        CancellationToken cancellationToken)
+    {
+        await using var scope = factory.Services.CreateAsyncScope();
+        var database = scope.ServiceProvider.GetRequiredService<WorkItemsDbContext>();
+        database.WorkItems.Add(workItem);
+        await database.SaveChangesAsync(cancellationToken);
+    }
+
+    private sealed record ProcessOverdueContract(
