@@ -0,0 +1,71 @@
+using WorkItems.Api.Contracts;
+
+namespace WorkItems.Api;
+
+internal sealed class CoalescingOverdueWorkItemProcessor(
+    OverdueWorkItemProcessor processor,
+    InProcessOverdueExecutionCoordinator executionCoordinator)
+    : IOverdueWorkItemProcessor
+{
+    public Task<ProcessOverdueResponse> ProcessAsync(CancellationToken cancellationToken) =>
+        executionCoordinator.ExecuteAsync(processor.ProcessAsync, cancellationToken);
+}
+
+internal sealed class InProcessOverdueExecutionCoordinator
+{
+    private readonly object syncRoot = new();
+    private Lazy<Task<ProcessOverdueResponse>>? activeExecution;
+
+    public async Task<ProcessOverdueResponse> ExecuteAsync(
+        Func<CancellationToken, Task<ProcessOverdueResponse>> operation,
+        CancellationToken cancellationToken)
+    {
+        ArgumentNullException.ThrowIfNull(operation);
+
+        while (true)
+        {
+            var candidateExecution = new Lazy<Task<ProcessOverdueResponse>>(
+                () => operation(cancellationToken),
+                LazyThreadSafetyMode.ExecutionAndPublication);
+            Lazy<Task<ProcessOverdueResponse>> selectedExecution;
+            bool ownsExecution;
+
+            lock (syncRoot)
+            {
+                selectedExecution = activeExecution ??= candidateExecution;
+                ownsExecution = ReferenceEquals(selectedExecution, candidateExecution);
+            }
+
+            Task<ProcessOverdueResponse>? executionTask = null;
+
+            try
+            {
+                executionTask = selectedExecution.Value;
+                return await executionTask.WaitAsync(cancellationToken);
+            }
+            catch (Exception) when (!ownsExecution && !cancellationToken.IsCancellationRequested)
+            {
+                // 首位執行者未取得可共享結果時，由仍有效的等待者依既有語意重試。
+            }
+            finally
+            {
+                if (executionTask is null || executionTask.IsCompleted)
+                {
+                    RemoveCompletedExecution(selectedExecution);
+                }
+            }
+        }
+    }
+
+    private void RemoveCompletedExecution(
+        Lazy<Task<ProcessOverdueResponse>> completedExecution)
+    {
+        lock (syncRoot)
+        {
+            if (ReferenceEquals(activeExecution, completedExecution))
+            {
+                activeExecution = null;
+            }
+        }
+    }
+}
