+    }
+
+    [Fact]
+    public async Task ConcurrentProcessing_WhenOwnerIsCanceled_AllowsWaitingCallerToRetry()
+    {
+        var cancellationToken = TestContext.Current.CancellationToken;
+        var firstNotificationEntered = new TaskCompletionSource(
+            TaskCreationOptions.RunContinuationsAsynchronously);
+        var attemptCount = 0;
+        using var factory = new WorkItemsApiFactory(
+            notificationHandler: async (_, token) =>
+            {
+                if (Interlocked.Increment(ref attemptCount) == 1)
+                {
+                    firstNotificationEntered.TrySetResult();
+                    await Task.Delay(Timeout.InfiniteTimeSpan, token);
+                }
+
+                return true;
+            });
+        var workItem = CreateDueWorkItem(factory.UtcNow);
+        await SeedAsync(factory, workItem, cancellationToken);
+        await using var firstScope = factory.Services.CreateAsyncScope();
+        await using var secondScope = factory.Services.CreateAsyncScope();
+        var firstProcessor = firstScope.ServiceProvider
+            .GetRequiredService<IOverdueWorkItemProcessor>();
+        var secondProcessor = secondScope.ServiceProvider
+            .GetRequiredService<IOverdueWorkItemProcessor>();
+        using var ownerCancellation = new CancellationTokenSource();
+
+        var canceledProcessing = firstProcessor.ProcessAsync(ownerCancellation.Token);
+        await firstNotificationEntered.Task.WaitAsync(cancellationToken);
+        var waitingProcessing = secondProcessor.ProcessAsync(cancellationToken);
+        await Task.Delay(TimeSpan.FromMilliseconds(100), cancellationToken);
+        await ownerCancellation.CancelAsync();
+
+        var exception = await Assert.ThrowsAnyAsync<OperationCanceledException>(
+            () => canceledProcessing);
+        var summary = await waitingProcessing;
+
+        Assert.Equal(ownerCancellation.Token, exception.CancellationToken);
+        Assert.Equal(1, summary.NotificationAttemptCount);
+        Assert.Equal(2, factory.Notifications.AttemptedWorkItemIds.Count);
+        Assert.Equal("Overdue", await ReadStatusAsync(factory, workItem.Id, cancellationToken));
+    }
+
+    private static OverdueProcessingWorker CreateWorker(WorkItemsApiFactory factory) =>
+        new(
+            factory.Services.GetRequiredService<IServiceScopeFactory>(),
