@@ -0,0 +1,47 @@
+using System.Collections.Concurrent;
+
+namespace WorkItems.Api;
+
+/// <summary>
+/// 防止同一個應用程式 Process 內重疊的逾期處理重複通知同一筆工作項目。
+/// </summary>
+public sealed class InProcessOverdueNotificationGuard
+{
+    private readonly ConcurrentDictionary<Guid, object> notificationsInProgress = new();
+
+    /// <summary>
+    /// 嘗試取得工作項目的進行中通知租約。
+    /// </summary>
+    /// <param name="workItemId">工作項目識別碼。</param>
+    /// <returns>取得租約時回傳可釋放物件；已有重疊通知時回傳 <see langword="null"/>。</returns>
+    public IDisposable? TryEnter(Guid workItemId)
+    {
+        var leaseMarker = new object();
+        return notificationsInProgress.TryAdd(workItemId, leaseMarker)
+            ? new NotificationLease(this, workItemId, leaseMarker)
+            : null;
+    }
+
+    private void Exit(Guid workItemId, object leaseMarker)
+    {
+        if (notificationsInProgress.TryGetValue(workItemId, out var currentMarker) &&
+            ReferenceEquals(currentMarker, leaseMarker))
+        {
+            notificationsInProgress.TryRemove(workItemId, out _);
+        }
+    }
+
+    private sealed class NotificationLease(
+        InProcessOverdueNotificationGuard owner,
+        Guid workItemId,
+        object leaseMarker) : IDisposable
+    {
+        private InProcessOverdueNotificationGuard? currentOwner = owner;
+
+        public void Dispose()
+        {
+            var ownerToRelease = Interlocked.Exchange(ref currentOwner, null);
+            ownerToRelease?.Exit(workItemId, leaseMarker);
+        }
+    }
+}
